-- Crear Base de datos ENUT

CREATE DATABASE IF NOT EXISTS enut2024
  CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE enut2024;

-- Tabla tvivienda 

CREATE TABLE `tvivienda` (
  `llaveviv` VARCHAR(9) NOT NULL COMMENT 'Llave de identificación de la vivienda',
  `p1_1` VARCHAR(1) NULL COMMENT '1.1 ¿De qué material es la mayor parte del piso de esta vivienda?',
  `p1_2` VARCHAR(1) NULL COMMENT '1.2 ¿Esta vivienda tiene cuarto para cocinar?',
  `p1_3` VARCHAR(2) NULL COMMENT '1.3 ¿Cuántos cuartos se usan para dormir, sin contar pasillos?',
  `p1_3a` VARCHAR(2) NULL COMMENT '1.3a ¿Cuántos cuartos tiene en total esta vivienda, contando la cocina? (No cuente pasillos ni baños)',
  `p1_4` VARCHAR(1) NULL COMMENT '1.4 ¿El agua la obtienen de llaves o mangueras que están...',
  `p1_5` VARCHAR(1) NULL COMMENT '1.5 ¿El agua que usan en su vivienda proviene...',
  `p1_6` VARCHAR(1) NULL COMMENT '1.6 Entonces, ¿acarrean el agua de...',
  `p1_7` VARCHAR(1) NULL COMMENT '1.7 ¿Cuántos días a la semana cuenta con agua en su vivienda?',
  `p1_8` VARCHAR(1) NULL COMMENT '1.8 ¿Tienen...',
  `p1_9` VARCHAR(1) NULL COMMENT '1.9 ¿La taza de baño (letrina)...',
  `p1_10` VARCHAR(1) NULL COMMENT '1.10 ¿Esta vivienda tiene drenaje o desagüe conectado a...',
  `p1_11` VARCHAR(1) NULL COMMENT '1.11 ¿Hay luz eléctrica en esta vivienda?',
  `p1_12` VARCHAR(1) NULL COMMENT '1.12 ¿El combustible que más usan para cocinar es...',
  `p1_13` VARCHAR(1) NULL COMMENT '1.13 ¿El fogón (anafre, estufa, comal) donde cocinan con leña o carbón tiene un tubo o chimenea para sacar el humo?',
  `p1_14` VARCHAR(1) NULL COMMENT '1.14 ¿La basura de esta vivienda...',
  `p1_15_01` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen lavadero?',
  `p1_15_02` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen fregadero o tarja?',
  `p1_15_03` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen tanque de gas estacionario o instalación para gas natural?',
  `p1_15_04` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen tinaco?',
  `p1_15_05` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen cisterna o aljibe?',
  `p1_15_06` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen bomba de agua?',
  `p1_15_07` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen regadera?',
  `p1_15_08` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen boiler o calentador de agua? (gas, eléctrico, leña)',
  `p1_15_09` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen calentador solar de agua?',
  `p1_15_10` VARCHAR(1) NULL COMMENT '1.15 ¿En esta vivienda tienen aire acondicionado?',
  `p2_1` VARCHAR(2) NULL COMMENT '2.1 ¿Cuántas personas viven normalmente en esta vivienda contando a bebés, niñas, niños, personas mayores y personas con discapacidad? Incluya también a las personas trabajadoras domésticas y huéspedes que duerman aquí.',
  `p2_2` VARCHAR(1) NULL COMMENT '2.2 ¿Todas las personas que viven en esta vivienda comparten un mismo gasto para comer?',
  `p2_3` VARCHAR(2) NULL COMMENT '2.3 Entonces, ¿cuántos hogares o grupos de personas tienen gasto separado para comer contando el de usted?',
  `cvegeo` VARCHAR(2) NULL COMMENT 'Clave geográfica',
  `cve_ent` VARCHAR(2) NULL COMMENT 'Entidad',
  `tloc` VARCHAR(1) NULL COMMENT 'Tamaño de Localidad',
  `menor10` VARCHAR(1) NULL COMMENT 'Variable indicadora del tamaño de localidad para explotación',
  `est_dis` VARCHAR(4) NULL COMMENT 'Estrato de Diseño Muestral',
  `upm_dis` VARCHAR(5) NULL COMMENT 'Unidad Primaria de Muestreo',
  `fac_viv` DECIMAL(5,0) NULL COMMENT 'Factor',
  `control` VARCHAR(7) NULL COMMENT 'Control de Vivienda',
  `viv_sel` VARCHAR(2) NULL COMMENT 'Número de Vivienda Seleccionada',
  PRIMARY KEY (`llaveviv`)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;

-- Tabla thogar 

CREATE TABLE `thogar` (
  `llavehog` VARCHAR(10) NOT NULL COMMENT 'Llave de identificación del hogar',
  `llaveviv` VARCHAR(9) NULL COMMENT 'Llave de identificación de la vivienda',
  `p2_4_01` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen televisor?',
  `p2_4_02` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen plancha eléctrica?',
  `p2_4_03` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen licuadora?',
  `p2_4_04` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen refrigerador?',
  `p2_4_05` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen lavadora?',
  `p2_4_05a` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen ¿Es automática (se llena, lava, enjuaga y exprime sola)?',
  `p2_4_06` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen secadora de ropa?',
  `p2_4_07` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen horno de microondas?',
  `p2_4_08` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen automóvil o camioneta?',
  `p2_4_09` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen motocicleta o motoneta?',
  `p2_4_10` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen bicicleta que se utilice como medio de transporte?',
  `p2_4_11` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen computadora, laptop o tablet?',
  `p2_4_12` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen teléfono celular o smartphone?',
  `p2_4_13` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen internet?',
  `p2_4_14` VARCHAR(1) NULL COMMENT '2.4 ¿En este hogar tienen servicio de películas, música o videos de paga por internet (Netflix, Claro video, HBO, Spotify, etcétera)?',
  `p3_14_1` VARCHAR(1) NULL COMMENT '3.14 En este hogar, ¿contratan personal para realizar trabajo doméstico (limpiar casa, planchar, cocinar)?',
  `p3_15_1` VARCHAR(1) NULL COMMENT '3.15 La semana pasada ¿cuántos días asistió a trabajar el personal para realizar trabajo doméstico (limpiar casa, planchar, cocinar)?',
  `p3_16_1` VARCHAR(2) NULL COMMENT '3.16 En total, ¿cuántas horas trabajó el personal para realizar trabajo doméstico (limpiar casa, planchar, cocinar), la semana pasada?',
  `p3_17_1` VARCHAR(5) NULL COMMENT '3.17 ¿Cuánto se pagó por el servicio que realizó este personal la semana pasada?',
  `p3_19_1` VARCHAR(1) NULL COMMENT '3.19 Cuando el personal para realizar trabajo doméstico (limpiar casa, planchar, cocinar) no asiste, ¿quién es la persona del hogar encargada de realizar estas labores?',
  `p3_14_2` VARCHAR(1) NULL COMMENT '3.14 En este hogar, ¿contratan personal de enfermería o para el cuidado o apoyo a personas mayores o con discapacidad?',
  `p3_15_2` VARCHAR(1) NULL COMMENT '3.15 La semana pasada ¿cuántos días asistió a trabajar el personal de enfermería o para el cuidado o apoyo a personas mayores o con discapacidad?',
  `p3_16_2` VARCHAR(2) NULL COMMENT '3.16 En total, ¿cuántas horas trabajó el personal de enfermería o para el cuidado o apoyo a personas mayores o con discapacidad, la semana pasada?',
  `p3_17_2` VARCHAR(5) NULL COMMENT '3.17 ¿Cuánto se pagó por el servicio que realizó este personal la semana pasada?',
  `p3_18_2` VARCHAR(1) NULL COMMENT '3.18 ¿Esta(s) persona(s) es(son)enfermera(s) o enfermero(s)',
  `p3_19_2` VARCHAR(1) NULL COMMENT '3.19 Cuando el personal de enfermería o para el cuidado o apoyo a personas mayores o con discapacidad no asiste, ¿quién es la persona del hogar encargada de realizar estas labores?',
  `p3_14_3` VARCHAR(1) NULL COMMENT '3.14 En este hogar, ¿contratan personal de enfermería o para el cuidado o atención a bebés, niñas y niños?',
  `p3_15_3` VARCHAR(1) NULL COMMENT '3.15 La semana pasada ¿cuántos días asistió a trabajar el personal de enfermería o para el cuidado o atención a bebés, niñas y niños?',
  `p3_16_3` VARCHAR(2) NULL COMMENT '3.16 En total, ¿cuántas horas trabajó el personal de enfermería o para el cuidado o atención a bebés, niñas y niños, la semana pasada?',
  `p3_17_3` VARCHAR(5) NULL COMMENT '3.17 ¿Cuánto se pagó por el servicio que realizó este personal la semana pasada?',
  `p3_18_3` VARCHAR(1) NULL COMMENT '3.18 ¿Esta(s) persona(s) es(son)enfermera(s) o enfermero(s)',
  `p3_19_3` VARCHAR(1) NULL COMMENT '3.19 Cuando el personal de enfermería o para el cuidado o atención a bebés, niñas y niños no asiste, ¿quién es la persona del hogar encargada de realizar estas labores?',
  `p3_20_1` VARCHAR(1) NULL COMMENT '3.20 Durante los últimos tres meses, ¿las personas de este hogar recibieron dinero de programas de apoyos del gobierno (pensión para personas mayores, jóvenes construyendo el futuro, becas para estudiar, etcétera)?',
  `p3_20a_1` VARCHAR(6) NULL COMMENT '3.20a ¿Cuánto recibieron en total? Declare en pesos',
  `p3_20_2` VARCHAR(1) NULL COMMENT '3.20 Durante los últimos tres meses, ¿las personas de este hogar recibieron dinero por jubilación o pensión?',
  `p3_20a_2` VARCHAR(6) NULL COMMENT '3.20a ¿Cuánto recibieron en total? Declare en pesos',
  `p3_20_3` VARCHAR(1) NULL COMMENT '3.20 Durante los últimos tres meses, ¿las personas de este hogar recibieron dinero de familiares o amistades que viven o se fueron a trabajar a otro país?',
  `p3_20a_3` VARCHAR(6) NULL COMMENT '3.20a ¿Cuánto recibieron en total? Declare en pesos',
  `p3_20_4` VARCHAR(1) NULL COMMENT '3.20 Durante los últimos tres meses, ¿las personas de este hogar recibieron dinero de familiares o amistades que viven en el país?',
  `p3_20a_4` VARCHAR(6) NULL COMMENT '3.20a ¿Cuánto recibieron en total? Declare en pesos',
  `p3_20_5` VARCHAR(1) NULL COMMENT '3.20 Durante los últimos tres meses, ¿las personas de este hogar recibieron dinero por el alquiler de algún bien (placas para taxi, automóvil, etcétera)?',
  `p3_20a_5` VARCHAR(6) NULL COMMENT '3.20a ¿Cuánto recibieron en total? Declare en pesos',
  `p3_20_6` VARCHAR(1) NULL COMMENT '3.20 Durante los últimos tres meses, ¿las personas de este hogar recibieron dinero por la renta de alguna propiedad (casa, edificio, local, terreno, tierra de cultivo, etcétera)?',
  `p3_20a_6` VARCHAR(6) NULL COMMENT '3.20a ¿Cuánto recibieron en total? Declare en pesos',
  `p3_20_7` VARCHAR(1) NULL COMMENT '3.20 Durante los últimos tres meses, ¿las personas de este hogar recibieron dinero por retiro de intereses bancarios?',
  `p3_20a_7` VARCHAR(6) NULL COMMENT '3.20a ¿Cuánto recibieron en total? Declare en pesos',
  `p3_20_8` VARCHAR(1) NULL COMMENT '3.20 Durante los últimos tres meses, ¿las personas de este hogar recibieron dinero por la venta o empeño de algún bien (casa, joyas, vehículos, maquinaria, animales,electrodomésticos, etcétera)?',
  `p3_20a_8` VARCHAR(6) NULL COMMENT '3.20a ¿Cuánto recibieron en total? Declare en pesos',
  `cvegeo` VARCHAR(2) NULL COMMENT 'Clave geográfica',
  `cve_ent` VARCHAR(2) NULL COMMENT 'Entidad',
  `tloc` VARCHAR(1) NULL COMMENT 'Tamaño de Localidad',
  `menor10` VARCHAR(1) NULL COMMENT 'Variable indicadora del tamaño de localidad para explotación',
  `est_dis` VARCHAR(4) NULL COMMENT 'Estrato de Diseño Muestral',
  `upm_dis` VARCHAR(5) NULL COMMENT 'Unidad Primaria de Muestreo',
  `fac_hog` DECIMAL(5,0) NULL COMMENT 'Factor',
  `control` VARCHAR(7) NULL COMMENT 'Control de Vivienda',
  `viv_sel` VARCHAR(2) NULL COMMENT 'Número de Vivienda Seleccionada',
  `hogar` VARCHAR(1) NULL COMMENT 'Número de Hogar en la Vivienda',
  PRIMARY KEY (`llavehog`),
  CONSTRAINT fk_thogar_llaveviv FOREIGN KEY (`llaveviv`)
    REFERENCES `tvivienda` (`llaveviv`)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;

-- Tabla TSDEM 

CREATE TABLE `tsdem` (
  `llavesde` VARCHAR(12) NOT NULL COMMENT 'Llave de identificación de la tabla sociodemográfica',
  `llaveviv` VARCHAR(9) NULL COMMENT 'Llave de identificación de la vivienda',
  `llavehog` VARCHAR(10) NULL COMMENT 'Llave de identificación del hogar',
  `paren` VARCHAR(1) NULL COMMENT '3.3 ¿Qué es (NOMBRE) de la (del) jefa(e) del hogar?',
  `parenc` VARCHAR(3) NULL COMMENT '3.3 ¿Qué es (NOMBRE) de la (del) jefa(e) del hogar? - Otro parentesco (codificada)',
  `sexo` VARCHAR(1) NULL COMMENT '3.4 (NOMBRE) es hombre (NOMBRE) es mujer',
  `edad` VARCHAR(2) NULL COMMENT '3.5 ¿Cuántos años cumplidos tiene (NOMBRE)?',
  `p3_6_1` VARCHAR(1) NULL COMMENT '3.6 En su vida diaria, ¿(NOMBRE) cuánta dificultad tiene para ver, aun usando lentes?',
  `p3_6_2` VARCHAR(1) NULL COMMENT '3.6 En su vida diaria, ¿(NOMBRE) cuánta dificultad tiene para oír, aun usando aparato auditivo?',
  `p3_6_3` VARCHAR(1) NULL COMMENT '3.6 En su vida diaria, ¿(NOMBRE) cuánta dificultad tiene para mover o usar sus brazos o manos?',
  `p3_6_4` VARCHAR(1) NULL COMMENT '3.6 En su vida diaria, ¿(NOMBRE) cuánta dificultad tiene para caminar, subir o bajar usando sus piernas?',
  `p3_6_5` VARCHAR(1) NULL COMMENT '3.6 En su vida diaria, ¿(NOMBRE) cuánta dificultad tiene para recordar o concentrarse?',
  `p3_6_6` VARCHAR(1) NULL COMMENT '3.6 En su vida diaria, ¿(NOMBRE) cuánta dificultad tiene para bañarse, vestirse o comer?',
  `p3_6_7` VARCHAR(1) NULL COMMENT '3.6 En su vida diaria, ¿(NOMBRE) cuánta dificultad tiene para hablar o comunicarse (por ejemplo, entender o ser entendido por otros)?',
  `p3_6_8` VARCHAR(1) NULL COMMENT '3.6 En su vida diaria, ¿(NOMBRE) cuánta dificultad tiene para realizar sus actividades diarias por alguna condición emocional o mental (con autonomía e independencia)? Condición de salud como autismo, depresión, bipolaridad, esquizofrenia, etcétera.',
  `p3_7` VARCHAR(1) NULL COMMENT '3.7 La semana pasada, (NOMBRE) por la dificultad que tiene para (RESPUESTA DE 3.6), ¿necesitó de los cuidados de otra persona?',
  `p3_8` VARCHAR(1) NULL COMMENT '3.8 La semana pasada, ¿(NOMBRE) necesitó de los cuidados de otra persona por tener alguna enfermedad crónica o temporal? ¿Necesitó cuidados por enfermedad...',
  `p3_9` VARCHAR(2) NULL COMMENT '3.9 Cuando (NOMBRE) tiene problemas de salud, ¿en dónde se atiende?',
  `p3_10` VARCHAR(1) NULL COMMENT '3.10 ¿(NOMBRE) asiste actualmente a educación inicial, estancia, guardería, preescolar o kínder?',
  `p3_11` VARCHAR(1) NULL COMMENT '3.11 ¿Cuál es la razón principal por la que (NOMBRE) no asiste a educación inicial, estancia, guardería, preescolar o kínder?',
  `p3_12` VARCHAR(1) NULL COMMENT '3.12 ¿(NOMBRE) asiste actualmente a la escuela?',
  `p3_13` VARCHAR(2) NULL COMMENT '3.13 ¿Cuál es la razón principal por la que (NOMBRE) no asiste o dejó de asistir a la escuela?',
  `cvegeo` VARCHAR(2) NULL COMMENT 'Clave geográfica',
  `cve_ent` VARCHAR(2) NULL COMMENT 'Entidad',
  `tloc` VARCHAR(1) NULL COMMENT 'Tamaño de Localidad',
  `menor10` VARCHAR(1) NULL COMMENT 'Variable indicadora del tamaño de localidad para explotación',
  `est_dis` VARCHAR(4) NULL COMMENT 'Estrato de Diseño Muestral',
  `upm_dis` VARCHAR(5) NULL COMMENT 'Unidad Primaria de Muestreo',
  `fac_hog` DECIMAL(5,0) NULL COMMENT 'Factor',
  `control` VARCHAR(7) NULL COMMENT 'Control de Vivienda',
  `viv_sel` VARCHAR(2) NULL COMMENT 'Número de Vivienda Seleccionada',
  `hogar` VARCHAR(1) NULL COMMENT 'Número de Hogar en la Vivienda',
  `n_ren` VARCHAR(2) NULL COMMENT 'Número de Renglón de la Persona',
  PRIMARY KEY (`llavesde`),
  CONSTRAINT fk_tsdem_llaveviv FOREIGN KEY (`llaveviv`)
    REFERENCES `tvivienda` (`llaveviv`),
  CONSTRAINT fk_tsdem_llavehog FOREIGN KEY (`llavehog`)
    REFERENCES `thogar` (`llavehog`)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;

-- Tabla tmodulo 

CREATE TABLE `tmodulo` (
  `llavemod` VARCHAR(12) NOT NULL COMMENT 'Llave de identificación de la persona elegida',
  `llaveviv` VARCHAR(9) NULL COMMENT 'Llave de identificación de la vivienda',
  `llavehog` VARCHAR(10) NULL COMMENT 'Llave de identificación del hogar',
  `sexo` VARCHAR(1) NULL COMMENT '3.4 (NOMBRE) es hombre (NOMBRE) es mujer',
  `edad_v` VARCHAR(2) NULL COMMENT 'Edad verificada',
  `p4_1` VARCHAR(1) NULL COMMENT '4.1 ¿Usted habla algún dialecto o lengua indígena?',
  `p4_1c` VARCHAR(4) NULL COMMENT '4.1c ¿Qué dialecto o lengua indígena habla? (Codificación de dialecto o lengua indígena)',
  `niv` VARCHAR(2) NULL COMMENT '4.2 ¿Hasta qué año o grado aprobó usted en la escuela? - Nivel',
  `gra` VARCHAR(1) NULL COMMENT '4.2 ¿Hasta qué año o grado aprobó usted en la escuela? - Grado',
  `p4_3` VARCHAR(1) NULL COMMENT '4.3 ¿Usted sabe leer y escribir un recado?',
  `p4_4` VARCHAR(1) NULL COMMENT '4.4 Por sus antepasados y de acuerdo con sus costumbres y tradiciones, ¿usted se considera afromexicana(o)negra(o) o afrodescendiente?',
  `p4_5` VARCHAR(1) NULL COMMENT '4.5 Actualmente, ¿usted es una persona...',
  `p4_6` VARCHAR(1) NULL COMMENT '4.6 Por sus costumbres y tradiciones, ¿usted se considera indígena?',
  `p4_7` VARCHAR(1) NULL COMMENT '4.7 ¿Se considera indígena principalmente...',
  `p5_1` VARCHAR(1) NULL COMMENT '5.1 Durante la semana pasada, ¿usted trabajó al menos una hora?',
  `p5_2` VARCHAR(1) NULL COMMENT '5.2 Dígame si para ganar dinero o ayudar al gasto del hogar, ¿la semana pasada usted...',
  `p5_3c` VARCHAR(4) NULL COMMENT '5.3 ¿Cuáles son las tareas o funciones principales que desempeñó en su trabajo (actividad) (principal) de la semana pasada?',
  `p5_5` VARCHAR(1) NULL COMMENT '5.5 En su trabajo (actividad) (principal) de la semana pasada, ¿usted fue...',
  `p5_6_1` VARCHAR(1) NULL COMMENT '5.6 Aunque no las use, ¿en su trabajo (principal) tiene derecho a licencia o incapacidad con goce de sueldo por enfermedad, accidente o maternidad (paternidad)?',
  `p5_6_2` VARCHAR(1) NULL COMMENT '5.6 Aunque no las use, ¿en su trabajo (principal) tiene derecho a vacaciones con goce de sueldo?',
  `p5_6_3` VARCHAR(1) NULL COMMENT '5.6 Aunque no las use, ¿en su trabajo (principal) tiene derecho a jubilación o pensión?',
  `p5_6_4` VARCHAR(1) NULL COMMENT '5.6 Aunque no las use, ¿en su trabajo (principal) tiene derecho a sistema de ahorro para el retiro (AFORE, SAR)?',
  `p5_6_5` VARCHAR(1) NULL COMMENT '5.6 Aunque no las use, ¿en su trabajo (principal) tiene derecho a guardería o estancia infantil?',
  `p5_6_6` VARCHAR(1) NULL COMMENT '5.6 Aunque no las use, ¿en su trabajo (principal) tiene derecho a licencia por cuidados maternos o paternos?',
  `p5_6_7` VARCHAR(1) NULL COMMENT '5.6 Aunque no las use, ¿en su trabajo (principal) tiene derecho a servicio médico (IMSS, ISSSTE, entre otros)?',
  `p5_6_8` VARCHAR(1) NULL COMMENT '5.6 Aunque no las use, ¿en su trabajo (principal) tiene derecho a crédito para la vivienda?',
  `p5_7` VARCHAR(1) NULL COMMENT '5.7 Durante la semana pasada, ¿realizó su trabajo (actividad) (principal)...',
  `p5_8_1_1` VARCHAR(2) NULL COMMENT '5.8 Durante la semana pasada, ¿en total cuánto tiempo dedicó a trabajar (su actividad) de forma presencial de lunes a viernes? - Horas',
  `p5_8_1_2` VARCHAR(2) NULL COMMENT '5.8 Durante la semana pasada, ¿en total cuánto tiempo dedicó a trabajar (su actividad) de forma presencial de lunes a viernes? - Minutos',
  `p5_8_1_3` VARCHAR(2) NULL COMMENT '5.8 Durante la semana pasada, ¿en total cuánto tiempo dedicó a trabajar (su actividad) de forma presencial sábado y domingo? - Horas ',
  `p5_8_1_4` VARCHAR(2) NULL COMMENT '5.8 Durante la semana pasada, ¿en total cuánto tiempo dedicó a trabajar (su actividad) de forma presencial sábado y domingo? - Minutos',
  `p5_8_2_1` VARCHAR(2) NULL COMMENT '5.8 Durante la semana pasada, ¿en total cuánto tiempo dedicó a trabajar (su actividad) de forma virtual de lunes a viernes? - Horas',
  `p5_8_2_2` VARCHAR(2) NULL COMMENT '5.8 Durante la semana pasada, ¿en total cuánto tiempo dedicó a trabajar (su actividad) de forma virtual de lunes a viernes? - Minutos',
  `p5_8_2_3` VARCHAR(2) NULL COMMENT '5.8 Durante la semana pasada, ¿en total cuánto tiempo dedicó a trabajar (su actividad) de forma virtual sábado y domingo? - Horas ',
  `p5_8_2_4` VARCHAR(2) NULL COMMENT '5.8 Durante la semana pasada, ¿en total cuánto tiempo dedicó a trabajar (su actividad) de forma virtual sábado y domingo? - Minutos',
  `p5_9_1` VARCHAR(2) NULL COMMENT '5.9 Durante la semana pasada, ¿cuánto tiempo utilizó en trasladarse de ida y vuelta para trabajar (a su actividad) de lunes a viernes? - Horas',
  `p5_9_2` VARCHAR(2) NULL COMMENT '5.9 Durante la semana pasada, ¿cuánto tiempo utilizó en trasladarse de ida y vuelta para trabajar (a su actividad) de lunes a viernes? - Minutos',
  `p5_9_3` VARCHAR(2) NULL COMMENT '5.9 Durante la semana pasada, ¿cuánto tiempo utilizó en trasladarse de ida y vuelta para trabajar (a su actividad) sábado y domingo? - Horas',
  `p5_9_4` VARCHAR(2) NULL COMMENT '5.9 Durante la semana pasada, ¿cuánto tiempo utilizó en trasladarse de ida y vuelta para trabajar (a su actividad) sábado y domingo? - Minutos',
  `p5_10` VARCHAR(5) NULL COMMENT '5.10 En total, ¿cuánto gana o recibe usted por trabajar (su actividad)?',
  `p5_10a` VARCHAR(1) NULL COMMENT '5.10a ¿Cada cuándo?',
