-- Tabla tvar_crea 

CREATE TABLE `tvar_crea` (
  `llavemod` VARCHAR(12) NOT NULL COMMENT 'Llave de identificación de la persona elegida',
  `llaveviv` VARCHAR(9) NULL COMMENT 'Llave de identificación de la vivienda',
  `llavehog` VARCHAR(10) NULL COMMENT 'Llave de identificación del hogar',
  `activ_prod_con_cp` VARCHAR(21) NULL COMMENT 'Actividades productivas o de trabajo, con cuidados pasivos',
  `activ_prod_sin_cp` VARCHAR(21) NULL COMMENT 'Actividades productivas o de trabajo',
  `activ_merc` VARCHAR(21) NULL COMMENT 'Trabajo para el mercado (incluye búsqueda de trabajo y traslados)',
  `trab_merc_pv` VARCHAR(21) NULL COMMENT 'Trabajo para el mercado',
  `tras_trab` VARCHAR(21) NULL COMMENT 'Traslados al trabajo',
  `bus_trab` VARCHAR(21) NULL COMMENT 'Búsqueda de trabajo',
  `prod_bien_trab_auto` VARCHAR(21) NULL COMMENT 'Producción de bienes para uso exclusivo del hogar',
  `trab_no_rem_vol` VARCHAR(21) NULL COMMENT 'Trabajo no remunerado doméstico, de cuidados y voluntario',
  `trab_no_rem_hog` VARCHAR(21) NULL COMMENT 'Trabajo doméstico no remunerado para el propio hogar',
  `prep_serv_alim` VARCHAR(21) NULL COMMENT 'Preparación y servicio de alimentos',
  `limp_viv` VARCHAR(21) NULL COMMENT 'Limpieza de la vivienda',
  `limp_rop` VARCHAR(21) NULL COMMENT 'Limpieza y cuidado de ropa y calzado',
  `mant_viv` VARCHAR(21) NULL COMMENT 'Mantenimiento, instalación y reparaciones menores de la vivienda y otros bienes del hogar',
  `compras_hog` VARCHAR(21) NULL COMMENT 'Compras',
  `pagos_tram_hog` VARCHAR(21) NULL COMMENT 'Pagos y trámites',
  `org_sup_hog` VARCHAR(21) NULL COMMENT 'Gestión y administración ',
  `trab_no_rem_con_cp` VARCHAR(21) NULL COMMENT 'Trabajo no remunerado de cuidado a integrantes del hogar, con cuidados pasivos',
  `trab_no_rem_cuid_hog` VARCHAR(21) NULL COMMENT 'Trabajo no remunerado de cuidado a integrantes del hogar',
  `cuid_esp_int_hog_con_cp` VARCHAR(21) NULL COMMENT 'Cuidados especiales a integrantes del hogar por enfermedad crónica, temporal o discapacidad, con cuidados pasivos ',
  `cuid_esp_int_hog_sin_cp` VARCHAR(21) NULL COMMENT 'Cuidados especiales a integrantes del hogar con enfermedad crónica, temporal o discapacidad',
  `cuid_int_0a5_con_cp` VARCHAR(21) NULL COMMENT 'Cuidado a integrantes del hogar de 0 a 5 años, con cuidados pasivos',
  `cuid_int_0a5_sin_cp` VARCHAR(21) NULL COMMENT 'Cuidado a integrantes del hogar de 0 a 5 años',
  `cuid_int_6a14_con_cp` VARCHAR(21) NULL COMMENT 'Cuidado a integrantes del hogar de 6 a 14 años, con cuidados pasivos',
  `cuid_int_6a14_sin_cp` VARCHAR(21) NULL COMMENT 'Cuidado a integrantes del hogar de 6 a 14 años',
  `cuid_int_15a59` VARCHAR(21) NULL COMMENT 'Cuidado a integrantes del hogar de 15 a 59 años',
  `cuid_int_60mas_con_cp` VARCHAR(21) NULL COMMENT 'Cuidado a integrantes del hogar de 60 años y más, con cuidados pasivos',
  `cuid_int_60mas_sin_cp` VARCHAR(21) NULL COMMENT 'Cuidado a integrantes del hogar de 60 años y más',
  `trab_no_rem_otros_hog` VARCHAR(21) NULL COMMENT 'Trabajo no remunerado como apoyo  a otros hogares y trabajo voluntario',
  `apoy_hog_fam` VARCHAR(21) NULL COMMENT 'Apoyo a otros hogares de familiares',
  `trab_dom_otros_hog_fam` VARCHAR(21) NULL COMMENT 'Trabajo doméstico para hogar familiar',
  `cuid_esp_disc_enf` VARCHAR(21) NULL COMMENT 'Cuidados especiales a personas de otros hogares familiares con enfermedad crónica, temporal o discapacidad',
  `cuid_per_otros_hog` VARCHAR(21) NULL COMMENT 'Cuidados propios de la edad a personas de otros hogares familiares',
  `trab_no_rem_no_fam` VARCHAR(21) NULL COMMENT 'Trabajo no remunerado como apoyo a hogares no familiares,6 trabajo comunitario y voluntario (Apoyo a otros hogares no familiares, a la comunidad y trabajo voluntario)',
  `prod_bien_hog_rural` VARCHAR(21) NULL COMMENT 'Producción bienes para  consumo exclusivo del hogar',
  `prep_serv_alim_rural` VARCHAR(21) NULL COMMENT 'Preparación y servicios de alimentos para el hogar ',
  `activ_cuid_per` VARCHAR(21) NULL COMMENT 'Actividades de cuidado personal',
  `activ_estud` VARCHAR(21) NULL COMMENT 'Actividades de estudio',
  `activ_conviv` VARCHAR(21) NULL COMMENT 'Actividades de convivencia y entretenimiento',
  `edad` VARCHAR(2) NULL COMMENT '3.5 ¿Cuántos años cumplidos tiene (NOMBRE)?',
  `sexo` VARCHAR(1) NULL COMMENT '3.4 (NOMBRE) es hombre (NOMBRE) es mujer',
  `niv` VARCHAR(2) NULL COMMENT '4.2 ¿Hasta qué año o grado aprobó usted en la escuela? - Nivel',
  `gra` VARCHAR(1) NULL COMMENT '4.2 ¿Hasta qué año o grado aprobó usted en la escuela? - Grado',
  `cvegeo` VARCHAR(2) NULL COMMENT 'Clave geográfica',
  `cve_ent` VARCHAR(2) NULL COMMENT 'Entidad',
  `tloc` VARCHAR(1) NULL COMMENT 'Tamaño de Localidad',
  `menor10` VARCHAR(1) NULL COMMENT 'Variable indicadora del tamaño de localidad para explotación',
  `escolaridad` VARCHAR(1) NULL COMMENT 'Escolaridad',
  `cond_ind` VARCHAR(1) NULL COMMENT 'Condición de adscripción indígena',
  `cond_disc` VARCHAR(1) NULL COMMENT 'Condición de discapacidad',
  `cond_aee` VARCHAR(1) NULL COMMENT 'Condición de actividad económica específica',
  `est_dis` VARCHAR(4) NULL COMMENT 'Estrato de Diseño Muestral',
  `upm_dis` VARCHAR(5) NULL COMMENT 'Unidad Primaria de Muestreo',
  `fac_per` DECIMAL(5,0) NULL COMMENT 'Factor',
  `control` VARCHAR(7) NULL COMMENT 'Control de Vivienda',
  `viv_sel` VARCHAR(2) NULL COMMENT 'Número de Vivienda Seleccionada',
  `hogar` VARCHAR(1) NULL COMMENT 'Número de Hogar en la Vivienda',
  `n_ren` VARCHAR(2) NULL COMMENT 'Número de Renglón de la Persona',
  PRIMARY KEY (`llavemod`),
  CONSTRAINT fk_tvar_crea_llaveviv FOREIGN KEY (`llaveviv`)
    REFERENCES `tvivienda` (`llaveviv`),
  CONSTRAINT fk_tvar_crea_llavehog FOREIGN KEY (`llavehog`)
    REFERENCES `thogar` (`llavehog`)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;

